  while (cursor < queue.length && queue.length < 1_200_000) { const index = queue[cursor++]; if (seen[index]) continue; seen[index] = 1; const offset = index * 4; const distance = Math.abs(pixels.data[offset] - target[0]) + Math.abs(pixels.data[offset + 1] - target[1]) + Math.abs(pixels.data[offset + 2] - target[2]) + Math.abs(pixels.data[offset + 3] - target[3]); if (distance > threshold * 3) continue; selected[index] = 255; const px = index % pixels.width; const py = Math.floor(index / pixels.width); left = Math.min(left, px); top = Math.min(top, py); right = Math.max(right, px); bottom = Math.max(bottom, py); if (px > 0) queue.push(index - 1); if (px + 1 < pixels.width) queue.push(index + 1); if (py > 0) queue.push(index - pixels.width); if (py + 1 < pixels.height) queue.push(index + pixels.width); }
